import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"革","description":"焦氏易林注 - 革","frontmatter":{"title":"革","description":"焦氏易林注 - 革"},"headers":[],"relativePath":"zh/classics/jiaoyilin/049.md","filePath":"zh/classics/jiaoyilin/049.md"}'),l={name:"zh/classics/jiaoyilin/049.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><h3 id="革-1" tabindex="-1">革 <a class="header-anchor" href="#革-1" aria-label="Permalink to “革”">​</a></h3><h3 id="革之乾" tabindex="-1">革之乾 <a class="header-anchor" href="#革之乾" aria-label="Permalink to “革之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>高原峻山，陸土少泉。草木林麓，喜得所蓄。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《革》象。伏艮，故曰高原、曰峻山。伏坤為陸土，坎為泉，坎伏，故曰少泉。震為草木、為喜，艮止，故曰蓄。○陸土，汲古作址大，依宋元本。</p><h3 id="革之坤" tabindex="-1">革之坤 <a class="header-anchor" href="#革之坤" aria-label="Permalink to “革之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>一門二關，結緝不便。峻道異路，日暮不到。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《革》象。坤為門，伏坎，數一，故曰一門。坎為關，坤數二，故曰二關。坤閉，故曰結緝。艮為道路，山高故曰峻道。蒙二至上正反艮，故曰異路。艮為日，坤為暮，艮止，故不到。多用革伏象。關，門牡也。一門數關，故結緝不便。</p><h3 id="革之屯" tabindex="-1">革之屯 <a class="header-anchor" href="#革之屯" aria-label="Permalink to “革之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>憂患解除，喜至慶來。坐立歡門，與樂為鄰。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎為憂患，震為解，為喜樂，艮為門、為坐。</p><h3 id="革之蒙" tabindex="-1">革之蒙 <a class="header-anchor" href="#革之蒙" aria-label="Permalink to “革之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>殊類異路，心不相慕。牝牛牡猳，鰥無室家。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為類，艮為路，二至上正覆艮，故曰殊類異路。坎為心，二至上艮震相反，故不相慕。坤為牝牛，坎為牡猳，艮為鰥、為家，坎為室，言牛豕殊類，雖一牝一牡，而不能配合，故無室家也。○殊，汲古訛疏，依宋元本。</p><h3 id="革之需" tabindex="-1">革之需 <a class="header-anchor" href="#革之需" aria-label="Permalink to “革之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>太王為父，季歷孝友。文武聖明，仁政興起。旦隆四國，載福綏厚。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為王、為父、為始，故曰太王。伏艮為季，坤為孝友、為文，兌剛為武，乾為仁聖，互離為晝，故曰旦。坤為國，兌西方金，數四，故曰四國。○季歷，宋本、汲古作正季，依元本。林詞歷敘周王之由。旦，周公名。四國，猶四方，非管蔡商奄。</p><h3 id="革之訟" tabindex="-1">革之訟 <a class="header-anchor" href="#革之訟" aria-label="Permalink to “革之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>臨河求鯉，燕婉失餌。屏氣攝息，不得鯉子。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坤為水、為河、為魚，坤柔順，故曰燕婉。巽為餌，坎失，故燕婉失餌。震為氣息，坤閉，故屏氣攝息。震為子，坤魚，故曰鯉子。坤喪，故不得。○失餌，汲古作笑弭，依宋元本。</p><h3 id="革之師" tabindex="-1">革之師 <a class="header-anchor" href="#革之師" aria-label="Permalink to “革之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>賈利求福，莫如南國。仁德所在，金玉為質。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為利，震為福、為南，坤為國，故曰南國。震為仁德，伏乾為金，震為玉。○質，宋元本作寶，依汲古。</p><h3 id="革之比" tabindex="-1">革之比 <a class="header-anchor" href="#革之比" aria-label="Permalink to “革之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>白虎赤憤，窺觀王庭。宮闕被甲，大小出征。天地煩潰，育子不嬰。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>革兌為虎、為西，故曰白虎。坎為赤、為憂憤。赤憤，猶丹憤也。袁高詩：茫茫蒼海間，丹憤何由伸。蓋與赤心同義，茲曰赤憤，言虎猛也，或疑憤當為幩，然虎旡飾朱幩之理，或又疑為羵。羵為土中怪羊，不能出游也。離為觀、為甲，坤為亂潰，乾為王，坎為宮室，伏震為徵，乾為大、為天，坤為小、為地，革二至上正反兌巽，兌毀折，巽散亂，而伏艮震，艮為嬰兒，震為覆艮，故嬰不能育也。○地，汲古作下，潰作憒，依宋元本。</p><h3 id="革之小畜" tabindex="-1">革之小畜 <a class="header-anchor" href="#革之小畜" aria-label="Permalink to “革之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>子車針虎，善人危殆。黃鳥悲鳴，傷國無輔。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>秦風黃鳥詩哀三良殉穆公葬。子車針虎，三良名也。伏震為子、為車，艮為虎，坎為針，故曰子車針虎。震為善、為人，坎危殆。艮為鳥，坤為黃，故曰黃鳥。震為鳴，坎為悲，坤為國。傷國無輔，言失賢人也。</p><h3 id="革之履" tabindex="-1">革之履 <a class="header-anchor" href="#革之履" aria-label="Permalink to “革之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>兩目失明，日暮無光。脛足跛曳，不可以行，頓於邱傍。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《萃》。○曳，各本皆作步，依《剝》之《萃》校。</p><h3 id="革之泰" tabindex="-1">革之泰 <a class="header-anchor" href="#革之泰" aria-label="Permalink to “革之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>羅網四張，鳥無所翔。征伐困極，饑寒不食。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為網羅，震卦數四，故曰四張。震為鳥、為翔、為征伐。坤為飢，乾為寒，兌口為食，坤閉，故不食。</p><h3 id="革之否" tabindex="-1">革之否 <a class="header-anchor" href="#革之否" aria-label="Permalink to “革之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>震為伯，震伏，故曰伯夷。艮為叔，互巽，故曰叔齊。餘詳《比》之《剝》。</p><h3 id="革之同人" tabindex="-1">革之同人 <a class="header-anchor" href="#革之同人" aria-label="Permalink to “革之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>疾貧望幸，賈販市並。開牢擇羊，多得大。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《坎》。○幸，宋元本作仕，非，依汲古。第二句各本皆作使伯行販，依元本《訟》之《遯》校。</p><h3 id="革之大有" tabindex="-1">革之大有 <a class="header-anchor" href="#革之大有" aria-label="Permalink to “革之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>南山之楊，其葉牂牂。嘉樂君子，為國寵光。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>首二句陳風詩。牂牂，《毛傳》盛貌。伏艮，納丙，故曰南山。艮為木，故曰楊。艮為君子、為光，坤為國。</p><h3 id="革之謙" tabindex="-1">革之謙 <a class="header-anchor" href="#革之謙" aria-label="Permalink to “革之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>東壁餘光，數暗不明。主母嫉妬，亂我事業。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震東，艮壁，艮又為光，故曰東壁餘光，言燭在東壁。艮為明，互坎故不明。坤母，震為主，故曰主母。坎為嫉妬，坤為事業、為亂，事詳《謙》之《屯》。</p><h3 id="革之豫" tabindex="-1">革之豫 <a class="header-anchor" href="#革之豫" aria-label="Permalink to “革之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>厭浥晨夜，道多湛露。瀐衣濡褲，重難以步。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>《詩召南》：&quot;厭浥行露，豈不宿夜，畏行多露&quot;，《傳》：&quot;厭浥濕意&quot;。震為晨，坤坎皆為夜，震為道。坎為瀐濕也，震為襦褲。坤為重，震為步，坎陷，故難。○厭浥，各本皆作迷行。瀐衣濡褲，宋元本作瀐我襦褲，汲古作沾濡襦褲，難以步，宋元本步作涉，汲古作不可步，俱依元本《未濟》之《損》校，始知此林宋元汲古本皆訛錯也。</p><h3 id="革之隨" tabindex="-1">革之隨 <a class="header-anchor" href="#革之隨" aria-label="Permalink to “革之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>目瞤足動，嘉喜有頃，舉家蒙寵。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《需》。第二句宋元本作喜如其願，不韻，依汲古。</p><h3 id="革之蠱" tabindex="-1">革之蠱 <a class="header-anchor" href="#革之蠱" aria-label="Permalink to “革之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>鷹鸇欲食，短兔困急。逃頭見尾，為害所賊。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為鷹鸇，震為兔，雉，雞屬，疑用巽象也。艮為頭、為尾，艮在外，故曰逃頭。三至五艮覆，故曰見尾。兌為見、為毀折，故為害。巽為賊。○逃頭，汲古作延頸，害作我，均依宋元本。</p><h3 id="革之臨" tabindex="-1">革之臨 <a class="header-anchor" href="#革之臨" aria-label="Permalink to “革之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>鼻移在項，枯葉傷生。下朽上滎，家擾不寧，失其金城。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通《遯》。艮為鼻，乾為首，鼻在首下，故曰移鼻在項。震為葉，巽隕落，故曰枯葉，故曰下朽。乾為榮，故曰上榮。艮為家、為城，乾為金，坤消，故失其金城。○下朽，汲古作下枯，依宋元本。</p><h3 id="革之觀" tabindex="-1">革之觀 <a class="header-anchor" href="#革之觀" aria-label="Permalink to “革之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>飛不遠去，法為罔待。祿養未富。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>乾為祿、為富，乾伏，故未富。○第二句汲古作汝為內傷，姑從宋元本，仍未協。汲古多&quot;終無災咎，君善安止&quot;二句，依宋本。</p><h3 id="革之噬嗑" tabindex="-1">革之噬嗑 <a class="header-anchor" href="#革之噬嗑" aria-label="Permalink to “革之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>倒基敗宮，重舌作凶。被髪夜行，迷亂相誤，亡失居止。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為基、為宮，正覆艮，故曰倒基敗宮。伏兌為舌，正覆兌，故曰重舌。震為髪、為行，坎為夜，正反震，故曰迷亂相誤，而失居止也。○宮，汲古訛筥。夜行，宋元本、汲古皆作長夜，亡失居止皆作深亡吉居，均依丁本。</p><h3 id="革之賁" tabindex="-1">革之賁 <a class="header-anchor" href="#革之賁" aria-label="Permalink to “革之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>亥午相錯，敗亂緒業，民不得作。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>離居午，艮居亥，離為敗亂，伏巽為緒，坎眾為民。《詩汜歷樞》雲：卯酉為革政，亥午為革命；又《漢書翼奉傳》：&quot;易有陰陽，詩有五際。&quot;孟康曰：五際，卯酉午戌亥，陰陽始終際會之歲，於此則有改變之政。</p><h3 id="革之剝" tabindex="-1">革之剝 <a class="header-anchor" href="#革之剝" aria-label="Permalink to “革之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>野麋畏人，俱入山谷。命短不長，為虎所得，死於牙腹。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為麋、為山谷，坤為畏、為死，故曰命短。艮為虎，坤為復，伏兌為牙。</p><h3 id="革之復" tabindex="-1">革之復 <a class="header-anchor" href="#革之復" aria-label="Permalink to “革之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>秋冬探巢，不得鵲雛。銜指北去，愧我少姬。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《屯》。</p><h3 id="革之無妄" tabindex="-1">革之無妄 <a class="header-anchor" href="#革之無妄" aria-label="Permalink to “革之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>雙鳧欲飛，俱歸稻池。經涉雈澤，為矢所射，傷我胸臆。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《旅》。</p><h3 id="革之大畜" tabindex="-1">革之大畜 <a class="header-anchor" href="#革之大畜" aria-label="Permalink to “革之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>天門開闢，牢戶寥廓。桎梏解脫，拘囚縱釋。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《泰》。</p><h3 id="革之頤" tabindex="-1">革之頤 <a class="header-anchor" href="#革之頤" aria-label="Permalink to “革之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>尼父孔丘，善釣鯉魚。羅網一舉，得獲萬頭，富我家居。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>上艮，故曰尼、曰丘。下震，坤虛，故曰孔丘。《史記孔子世家》：&quot;叔梁紇禱尼丘，生孔子，字仲尼。&quot;《左傳哀十六年》：&quot;孔丘卒，哀公誄之曰：鳴呼哀哉，尼父無自律&quot;。坤為魚、為羅網，為萬。艮為首，故曰萬頭。艮為家，坤多，故曰富。○網，宋本作釣，元本作鉤，依汲古。</p><h3 id="革之大過" tabindex="-1">革之大過 <a class="header-anchor" href="#革之大過" aria-label="Permalink to “革之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>彭生為豕，暴龍作賊。盜堯衣裳，桀跖荷兵。青禽照夜，三旦夷亡。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>○豕，各本多作妖，於象不合。桀作聚，依《比》之《蒙》校。</p><h3 id="革之坎" tabindex="-1">革之坎 <a class="header-anchor" href="#革之坎" aria-label="Permalink to “革之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>華言風語，亂相誑誤。終無凶事，安寧如故。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《咸》之《頤》。○誑，宋本作狂，依元本、汲古。</p><h3 id="革之離" tabindex="-1">革之離 <a class="header-anchor" href="#革之離" aria-label="Permalink to “革之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>延頸見足，身困名辱。欲隱避仇，為害所賊。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏艮為頸，震為足，離為見，艮為身、為名，二四艮覆，故曰困辱。伏坎為隱伏、為仇、為害賊。○延，宋元本作逃，名作不，皆非，依汲古。賊，汲古作滅，依宋元本。</p><h3 id="革之咸" tabindex="-1">革之咸 <a class="header-anchor" href="#革之咸" aria-label="Permalink to “革之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>無足斷跟，居處不安，凶惡為殘。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《大過》。汲古多君臣相得四字，依宋元本。跟，汲古訛垠。</p><h3 id="革之恒" tabindex="-1">革之恒 <a class="header-anchor" href="#革之恒" aria-label="Permalink to “革之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>三人俱行，北求大牂。長孟病足，倩季負糧。柳下之寶，不失我邦。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《豐》。寶，依校各本皆作貞。我邦，宋元本、汲古皆作驪黃，皆非，依汲古《渙》之《豫》校。糧，宋元本作囊，依汲古。此林屢見糧皆作囊，致難索解，獨此處存其真。季者，季路。《家語》子路曰：吾嘗為親負米百裡之外，心甚樂之。林用此事，以此見汲古本真可貴也。</p><h3 id="革之遯" tabindex="-1">革之遯 <a class="header-anchor" href="#革之遯" aria-label="Permalink to “革之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>退飛見祥，傷敗毀墜。守小失大，功名小遂。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為飛，陰消陽，故曰退飛。祥，猶兆也。凡吉凶之兆先見者，皆曰祥。伏兌，故曰見。巽為隕落，故曰傷敗毀墜。艮為守，陰小陽大，陰消陽，故曰失大。艮為名。《左傳僖十六年》六鷁退飛，過宋都，宋襄公曰：是何祥也。註：祥，吉凶之先見者，後戰於泓，不擊半濟，不殺二毛，襄公果敗，故曰守小失大。</p><h3 id="革之大壯" tabindex="-1">革之大壯 <a class="header-anchor" href="#革之大壯" aria-label="Permalink to “革之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>持心瞿目，善搖數動。不安其處，散渙府藏，利得無有。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏艮為目，乾惕，故持心瞿目。震為動搖，震往，故曰善搖數動，不安其處。伏巽風，故曰散渙。坤為府藏，巽為利，坤亡，故無利。○搖數，宋元本作數搖，末句作無有利得，均依汲古。瞿目，各本訛懼怒，從《震》之《離》校。瞿，驚視也。林意似指呂媭散棄財寶事。</p><h3 id="革之晉" tabindex="-1">革之晉 <a class="header-anchor" href="#革之晉" aria-label="Permalink to “革之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>牽尾不前，逆理失臣。衛朔以奔。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>○衛，依《比》之《恆》校，各本皆作惠，非。</p><h3 id="革之明夷" tabindex="-1">革之明夷 <a class="header-anchor" href="#革之明夷" aria-label="Permalink to “革之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>祿如周公，父子俱封。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為周、為公、為父、為子。○汲古多建國洛東，在第二句，宋元本無。</p><h3 id="革之家人" tabindex="-1">革之家人 <a class="header-anchor" href="#革之家人" aria-label="Permalink to “革之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>君有八人，信允篤誠，為堯所舉。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為君、為人，巽數八，故曰八人。坎為信、為誠篤，震為帝，故曰堯。○君，宋元本作吾，依汲古。誠，汲古作敏，元本訛畒，依宋本。</p><h3 id="革之睽" tabindex="-1">革之睽 <a class="header-anchor" href="#革之睽" aria-label="Permalink to “革之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>久陰霖雨，泥塗行潦。商人休止，市空無寶。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《大過》。</p><h3 id="革之蹇" tabindex="-1">革之蹇 <a class="header-anchor" href="#革之蹇" aria-label="Permalink to “革之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>無足斷跟，居處不安，凶惡為殘。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>見前《咸》卦。</p><h3 id="革之解" tabindex="-1">革之解 <a class="header-anchor" href="#革之解" aria-label="Permalink to “革之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>馬蹄躓車，婦惡破家。青蠅污白，恭子離居。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《隨》。蹄，音踶，足相躗曰蹄。</p><h3 id="革之損" tabindex="-1">革之損 <a class="header-anchor" href="#革之損" aria-label="Permalink to “革之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>噂噂所言，莫如我垣。歡喜堅固，可以長安。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《困》。</p><h3 id="革之益" tabindex="-1">革之益 <a class="header-anchor" href="#革之益" aria-label="Permalink to “革之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>懿公淺愚，不受深謀。無遠失國，為狄所賊。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《家人》。賊，汲古作滅，依宋元本。</p><h3 id="革之夬" tabindex="-1">革之夬 <a class="header-anchor" href="#革之夬" aria-label="Permalink to “革之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>騏驥綠耳，章明造父。伯夙奏獻，衰續厥緒。佐文成伯，為晉元輔。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>《史記晉世家》造父幸於周繆王，取驥之乘匹驊騮綠耳獻之繆王，王使造父御西巡守，乃賜造父以趙城，十二世生趙夙，事晉獻公，夙之孫曰趙衰，事晉文公成伯業。乾為馬、為父、為大明。章明者，言始顯也。遇卦革伏震為伯，坤為夙，艮手為奏、為獻。奏，進也。奏獻者，言進事獻公也。巽為緒，離為文，震為晉。○驥，元本作鱗，依宋本、汲古。伯夙，汲古作夙伯，奏作所，依宋元本。衰，各本皆作襄，依《節》之《泰》校。</p><h3 id="革之姤" tabindex="-1">革之姤 <a class="header-anchor" href="#革之姤" aria-label="Permalink to “革之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>駕車入里，求鮮魴鯉。非其肆居，自令後市。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為車、為里，震為駕，巽為魚、為市肆，震為後，言里非產魚之地，故求之不得。○入，汲古作十，依宋元本。</p><h3 id="革之萃" tabindex="-1">革之萃 <a class="header-anchor" href="#革之萃" aria-label="Permalink to “革之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>求麞嘉鄉，惡地不行。道止中返，喜還其床。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為麞、為鄉，坤為惡，坤閉，故曰惡地不行。艮為道、為止、為床，伏震為反、為還。○返，宋元本作遷，還作反，均依汲古。</p><h3 id="革之升" tabindex="-1">革之升 <a class="header-anchor" href="#革之升" aria-label="Permalink to “革之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>杖鳩負裝，醉卧道傍。不知何公，竊我錦囊。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤文為鳩，互震故曰杖鳩。白貼雲：老人食多咽，刻鳩為杖，取鳩食不咽之義。震為裝、為道，伏艮為卧，坤迷，故曰醉卧。震為公，巽為盜，坤為囊。坤文，故曰錦囊。○杖，汲古作使，錦作衣，均依宋元本。</p><h3 id="革之困" tabindex="-1">革之困 <a class="header-anchor" href="#革之困" aria-label="Permalink to “革之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>登昆侖，入天門。過糟丘，宿玉泉。同惠歡，見仁君。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《姤》。三字句。仁，宋元本作欣，非。</p><h3 id="革之井" tabindex="-1">革之井 <a class="header-anchor" href="#革之井" aria-label="Permalink to “革之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>水為火牡，患厭不起。季伯夜行，與喜相逢。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>《左傳昭七年》：水，火之牡也。卦水火相交，故曰水為火牡。坎為患、為夜，伏艮為季，震為伯、為行、為喜。○牡，宋元本皆訛莊，汲古訛木為大床，依丁本。喜，汲古訛善。</p><h3 id="革之革" tabindex="-1">革之革 <a class="header-anchor" href="#革之革" aria-label="Permalink to “革之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>馬服長股，宜行善市。蒙佑諧偶，獲金五倍。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>乾為馬，巽為股、為長，故曰馬服長股。服，猶駕也。乾為金，巽為市、為倍，卦數五，故曰獲金五倍。○市，元本作布，依宋本。第三句汲古作俱蒙福佑，五作三，俱依宋元本。</p><h3 id="革之鼎" tabindex="-1">革之鼎 <a class="header-anchor" href="#革之鼎" aria-label="Permalink to “革之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>烏孫氏女，深目黑醜。嗜欲不同，過時無耦。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。艮為烏、為孫，坤女，互大離，故曰深目。坤為黑、為醜，坎為嗜欲，艮時，坤寡，故過時無耦。</p><h3 id="革之震" tabindex="-1">革之震 <a class="header-anchor" href="#革之震" aria-label="Permalink to “革之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>子鋤執麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《同人》。○經元，宋元本作元陰，汲古作陰元，依汲古《訟》之《同人》校。</p><h3 id="革之艮" tabindex="-1">革之艮 <a class="header-anchor" href="#革之艮" aria-label="Permalink to “革之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>灼火泉源，釣魴山巔。魚不可得，火不肯然。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>○火，宋元本訛炭，肯作可，依《比》之《屯》校。</p><h3 id="革之漸" tabindex="-1">革之漸 <a class="header-anchor" href="#革之漸" aria-label="Permalink to “革之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>天馬五道，炎火久處。往來上下，作文約己。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>衣枲絲麻，相隨笑歌，凶惡如何。義不可曉，恐多訛字，故不釋象。</p><h3 id="革之歸妹" tabindex="-1">革之歸妹 <a class="header-anchor" href="#革之歸妹" aria-label="Permalink to “革之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>鴟鴞破斧，沖人危殆。賴旦忠德，轉禍為福，傾危復立。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《蠱》。</p><h3 id="革之豐" tabindex="-1">革之豐 <a class="header-anchor" href="#革之豐" aria-label="Permalink to “革之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>牡飛門啟，憂患大解，不為身禍。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《兌》。</p><h3 id="革之旅" tabindex="-1">革之旅 <a class="header-anchor" href="#革之旅" aria-label="Permalink to “革之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>石門晨門，荷蕢食貧。遁世隱居，竟不逢時。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>《論語》子路宿於石門，晨門曰奚自。又子擊磬於衛，有荷蕢過門者曰：有心哉，擊磬乎。註：晨門荷蕢，皆隱者。艮為石、為門，伏震為晨、為蕢，艮為荷，兌為食，離虛，故曰食貧。艮為世，巽伏，故曰遁世隱居。艮為時。○晨門，宋元本作晨開，食作疾，皆非，從汲古。</p><h3 id="革之巽" tabindex="-1">革之巽 <a class="header-anchor" href="#革之巽" aria-label="Permalink to “革之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>免聚東郭，眾犬俱獵。圍缺不成，無所能獲。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《坤》。</p><h3 id="革之兌" tabindex="-1">革之兌 <a class="header-anchor" href="#革之兌" aria-label="Permalink to “革之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>三羊群走，雉兔驚駭。非所畏懼，自令勞苦。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌羊，離卦數三，故曰三羊群走。離為雉，伏震為兔、為驚駭，伏坎為畏、為勞。</p><h3 id="革之渙" tabindex="-1">革之渙 <a class="header-anchor" href="#革之渙" aria-label="Permalink to “革之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>羽翮病傷，無以為強。宋公德薄，敗於水泓。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為羽翮，坎為病，故曰羽翮病傷。震為公，《說文》以木架屋曰宋，艮象也，故曰宋公。下坎，故曰泓水。《左傳》宋襄公與楚戰，敗於泓。</p><h3 id="革之節" tabindex="-1">革之節 <a class="header-anchor" href="#革之節" aria-label="Permalink to “革之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>姬薑稚叔，三人偶食。論仁議福，以安王室。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為姬，伏巽為薑，艮少，故曰稚叔。震數三，兌食，兌卦數二，故曰三人偶食。震為言、為仁、為王，坎為室。○稚，宋元本訛雅，依汲古。</p><h3 id="革之中孚" tabindex="-1">革之中孚 <a class="header-anchor" href="#革之中孚" aria-label="Permalink to “革之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>精誠所在，神人為輔。德教之中，彌世長久。三聖乃興，多受福祉。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為精誠、為神、為人、為德教、為福祉，數三，故曰三聖。革互乾為聖，文、武、周公也。○之中，汲古作亡患，乃興作仍事，依宋元本。又神人為輔，宋元本作神為人輔，非，依汲古。</p><h3 id="革之小過" tabindex="-1">革之小過 <a class="header-anchor" href="#革之小過" aria-label="Permalink to “革之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>岐周海隅，獨樂不憂。可以避難，全身保才。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為周，艮山，故曰岐周。兌為海，震為樂，巽寡，故曰獨樂。巽伏，故曰避難。艮為保、為身。○才，汲古作財，依宋元本。</p><h3 id="革之既濟" tabindex="-1">革之既濟 <a class="header-anchor" href="#革之既濟" aria-label="Permalink to “革之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>孤獨特處，莫依為輔，心勞志苦。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《艮》。</p><h3 id="革之未濟" tabindex="-1">革之未濟 <a class="header-anchor" href="#革之未濟" aria-label="Permalink to “革之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>顧望登臺，意常欲逃。賈辛丑惡，妻不安夫。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>離為顧望、為醜惡，坎夫離妻，離卦在上，故妻不安夫。《左傳昭二十八年》魏獻子謂賈辛曰：昔賈大夫惡，娶妻而美，三年不言不笑。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
